exec('import csv,os,yfinance as yf\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip())\nrows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]\nlatest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\nf="virtual_portfolio.csv"; positions=[]\nif os.path.exists(f):\n positions=list(csv.DictReader(open(f,encoding="utf-8")))\nopen_tickers={p["ticker"] for p in positions if p["status"]=="OPEN"}\nrate=float(yf.download("EURUSD=X",period="5d",progress=False,auto_adjust=True)["Close"].dropna().iloc[-1].squeeze())\nfor t,r in latest.items():\n if r["signal"]=="ACHAT" and t not in open_tickers:\n  currency="EUR" if t.endswith((".PA",".AS")) else "USD"; price=float(r["price"]); quantity=1000/price if currency=="EUR" else 1000*rate/price; positions.append({"ticker":t,"entry_date":r["date"],"entry_price":round(price,4),"currency":currency,"eurusd_entry":round(rate,6) if currency=="USD" else 1,"quantity":round(quantity,6),"invested_eur":1000,"status":"OPEN"}); print("ACHAT VIRTUEL :",t,"| 1000 EUR | Quantite :",round(quantity,6),"| Prix :",price,currency)\nwith open(f,"w",newline="",encoding="utf-8") as q:\n fields=["ticker","entry_date","entry_price","currency","eurusd_entry","quantity","invested_eur","status"]; w=csv.DictWriter(q,fieldnames=fields); w.writeheader(); w.writerows(positions)\nprint("Portefeuille virtuel sauvegarde :",f)')
